placeorder.lean:
import LeanFM.Session.Syntax

/-- What the client orders. -/
structure CreateOrder where
  item : String
  quantity : Nat

/-- The shop's price for the order, in cents. -/
structure Quote where
  price : Nat

/-- The client pays; the card number is a secret, never logged. -/
structure Pay where
  amount : Nat
  card_secr : String

structure Charge where
  amount : Nat
  card_secr : String

structure Receipt where
  amount : Nat

/-- Placing an order: quote, pay, charge the card. -/
protocol PlaceOrder (Client, Shop, Bank) {
  o: CreateOrder from Client to Shop route "POST /orders";
  choice {
    q: Quote from Shop to Client cause o status 201;
    p: Pay from Client to Shop cause q where p.amount = q.price;
    c: Charge from Shop to Bank cause p;
    choice {
      d: Charged from Bank to Shop cause c;
      Receipt from Shop to Client cause d status 200;
    } or {
      x: Declined from Bank to Shop cause c;
      PaymentDeclined from Shop to Client cause x status 402;
    }
  } or {
    SoldOut from Shop to Client cause o status 409;
  }
}

construct-loop.lean:
protocol Poll (A, B) {
  loop L {
    choice {
      q: Ask from A to B;
      Answer from B to A cause q;
      continue L;
    } or {
      Bye from A to B;
    }
  }
}

construct-bounded-loop.lean:
protocol Retry (A, B) {
  loop Try at most 3 {
    q: Ask from A to B;
    choice {
      Ok from B to A cause q;
    } or {
      Busy from B to A cause q;
      continue Try;
    }
  } otherwise {
    GiveUp from A to B;
  }
}

construct-parallel.lean:
protocol Both (A, B, C) {
  parallel {
    q: Ask from A to B;
    Answer from B to A cause q;
  } and {
    r: Ask2 from A to C;
    Answer2 from C to A cause r;
  }
}

include.lean:
structure Login where
  user : String
structure LoggedIn where
  sid : Header (Fresh String)
structure Logout where
  sid : Header (Link String)
structure Create where
  token : Header (Link String)
  item : String
structure Made where
  token : Header (Link String)
  orderId : Fresh String

protocol Order (Client, Shop) given token {
  c: Create from Client to Shop;
  Made from Shop to Client cause c;
}

protocol Site (Customer, Store) {
  l: Login from Customer to Store;
  LoggedIn from Store to Customer cause l;
  include Order Customer Store with token = sid;
  o: Logout from Customer to Store;
  Bye from Store to Customer cause o;
}

race.lean:
protocol Race (Client, Shop) {
  choice {
    Cancel from Client to Shop;
  } or {
    Ship from Shop to Client;
  }
}

blind.lean:
protocol Blind (Client, Shop, Bank) {
  h: Hold from Client to Bank;
  choice {
    Capture from Shop to Bank;
    Ship from Shop to Client;
  } or {
    SoldOut from Shop to Client;
  }
}

borrow.lean:
protocol Borrow (Client, Shop, Bank) {
  q: Quote from Shop to Client;
  Paid from Bank to Client cause q;
}

jam.lean:
protocol Jam (A, B[1], C) {
  X from A to B;
  Y from C to B;
}
